#include <iostream>
#include <variant>
#include <string>
struct Add { int amount{}; };
struct Remove { int amount{}; };
using Command = std::variant<Add, Remove>;
bool executeStock(int& stock, const Command& command) {
    if (const auto* add = std::get_if<Add>(&command)) {
        if (add->amount < 0 || add->amount > 1000 - stock) { return false; }
        stock += add->amount;
        return true;
    }
    const auto* remove = std::get_if<Remove>(&command);
    if (!remove || remove->amount < 0 || remove->amount > stock) { return false; }
    stock -= remove->amount;
    return true;
}
int main() {
    Command value = Add{4};
    std::cout << (std::get_if<Remove>(&value) == nullptr) << '\n';
    int stock{3};
    bool ok = executeStock(stock, value);
    std::cout << ok << ' ' << stock << '\n';
}

